BEGIN;

-- No entitlement, quota, override, or existing provider state is inferred.
ALTER TABLE "SystemControl"
  ADD COLUMN "dodoEnvironment" TEXT,
  ADD COLUMN "dodoBusinessId" TEXT,
  ADD CONSTRAINT "SystemControl_dodo_binding_check" CHECK (
    ("dodoEnvironment" IS NULL AND "dodoBusinessId" IS NULL) OR
    ("dodoEnvironment" IS NOT NULL AND "dodoEnvironment" = 'test_mode' AND "dodoBusinessId" IS NOT NULL AND length(btrim("dodoBusinessId")) > 0)
  );

ALTER TABLE "BillingSubscription"
  ADD COLUMN "ownerIdSnapshot" TEXT,
  ADD COLUMN "settledPaymentId" TEXT,
  ADD COLUMN "paymentConfirmedAt" TIMESTAMP(3),
  ALTER COLUMN "userId" DROP NOT NULL;
ALTER TABLE "BillingSubscription" ADD CONSTRAINT "BillingSubscription_settlement_check" CHECK (
  ("settledPaymentId" IS NULL AND "paymentConfirmedAt" IS NULL) OR
  ("settledPaymentId" IS NOT NULL AND length(btrim("settledPaymentId")) > 0 AND "paymentConfirmedAt" IS NOT NULL AND "periodStart" IS NOT NULL AND "periodEnd" IS NOT NULL)
);
UPDATE "BillingSubscription" SET "ownerIdSnapshot" = "userId";
ALTER TABLE "BillingSubscription" DROP CONSTRAINT "BillingSubscription_userId_fkey";
ALTER TABLE "BillingSubscription" ADD CONSTRAINT "BillingSubscription_userId_fkey"
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "CheckoutAttempt"
  ADD COLUMN "ownerIdSnapshot" TEXT,
  ADD COLUMN "checkoutUrl" TEXT,
  ADD COLUMN "failureCode" TEXT,
  ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ALTER COLUMN "userId" DROP NOT NULL,
  ALTER COLUMN "billingCurrency" DROP NOT NULL;
UPDATE "CheckoutAttempt" SET "ownerIdSnapshot" = "userId";
ALTER TABLE "CheckoutAttempt" DROP CONSTRAINT "CheckoutAttempt_userId_fkey";
ALTER TABLE "CheckoutAttempt" ADD CONSTRAINT "CheckoutAttempt_userId_fkey"
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Fail migration if conflicting historical attempts need review; never delete
-- or silently close them. Wall-clock expiry is handled under the owner lock.
CREATE UNIQUE INDEX "CheckoutAttempt_one_open_per_user"
  ON "CheckoutAttempt" ("userId")
  WHERE "userId" IS NOT NULL AND "status" IN ('CREATING', 'CUSTOMER_CREATING', 'READY', 'UNKNOWN');

COMMIT;
